{
  "queryId": "eupid-sdjwt",
  "name": "EuPid identity check",
  "description": "Requests name and age attestation from the EU Personal ID",
  "enabled": true,
  "dcqlQuery": {
    "credentials": [
      {
        "id": "eupid",
        "format": "dc+sd-jwt",
        "meta": {
          "vct_values": ["{{tenantGatewayUrl}}/public/schema/vct/EuPid"]
        },
        "claims": [
          { "path": ["family_name"] },
          { "path": ["given_name"] },
          { "path": ["age_over_18"] }
        ]
      }
    ]
  }
}

{
  "queryId": "mdl-mdoc",
  "name": "Driving licence check",
  "description": "Requests the holder name from the mobile driving licence",
  "enabled": true,
  "dcqlQuery": {
    "credentials": [
      {
        "id": "mdl",
        "format": "mso_mdoc",
        "meta": {
          "doctype_value": "org.iso.18013.5.1.mDL"
        },
        "claims": [
          { "path": ["org.iso.18013.5.1", "family_name"] },
          { "path": ["org.iso.18013.5.1", "given_name"] }
        ]
      }
    ]
  }
}

{
  "queryId": "eupid-and-mdl",
  "name": "Identity and driving licence",
  "description": "Requests the EuPid and the mobile driving licence in one presentation",
  "enabled": true,
  "dcqlQuery": {
    "credentials": [
      {
        "id": "eupid",
        "format": "dc+sd-jwt",
        "meta": {
          "vct_values": ["{{tenantGatewayUrl}}/public/schema/vct/EuPid"]
        },
        "claims": [
          { "path": ["family_name"] },
          { "path": ["given_name"] }
        ]
      },
      {
        "id": "mdl",
        "format": "mso_mdoc",
        "meta": {
          "doctype_value": "org.iso.18013.5.1.mDL"
        },
        "claims": [
          { "path": ["org.iso.18013.5.1", "family_name"] },
          { "path": ["org.iso.18013.5.1", "given_name"] }
        ]
      }
    ]
  }
}

